  const protocols = [
    { name: 'TCP', description: 'Transmission Control Protocol' },
    { name: 'UDP', description: 'User Datagram Protocol' },
    { name: 'HTTP', description: 'Hypertext Transfer Protocol' }
  ];

  const handleProtocolSelect = (protocolName) => {
    setSelectedProtocol(protocolName);
  };

  return (
    <>
      <h1>Networking Fundamentals</h1>
      <p>Learn about different network protocols by selecting one below:</p>

      {protocols.map((protocol) => (
        <button 
          key={protocol.name}
          onClick={() => handleProtocolSelect(protocol.name)}
          style={{ /* Add conditional styling here */ }}
        >
          {protocol.name}
        </button>
      ))}

      {selectedProtocol && (
        <div>
          <h3>{selectedProtocol} Details</h3>
          <p>
            {protocols.find(p => p.name === selectedProtocol)?.description}
          </p>
        </div>
      )}
    </>
  );
};

